KycModule.runCheck.source:
async runCheck(userId: string): Promise<KycResult> {
  const identity = await this.identity.fetchIdentity(userId);
  const [birth, nationality] = await Promise.all([this.birthInfo.resolve(identity), this.nationality.resolve(identity)]);
  const screening = await this.sanctions.screen({
    name: identity.fullName,
    countryOfBirth: birth.countryOfBirth,
    nationality: nationality.alpha3,
  });
  const tier = riskTier({ countryOfBirth: birth.countryOfBirth, nationality: nationality.alpha3, screeningScore: screening.score });
  const previous = await this.getStatus(userId);
  const review = !screening.hit && needsManualReview(tier, previous);
  const status: KycStatus = screening.hit ? 'failed' : review ? 'pending_review' : 'passed';
  const result: KycResult = { userId, status, riskTier: tier, checkedAt: new Date().toISOString() };
  await this.persist(result, previous);
  if (review) {
    await this.outbox.enqueue('kyc.manual_review_requested', { userId, tier, listVersion: screening.listVersion });
  } else {
    await this.outbox.enqueue('kyc.completed', { ...result });
  }
  return result;
}

IdentityModule.fetchIdentity.source:
async fetchIdentity(userId: string): Promise<IdentityData> {
  const docs = await this.documents.latestDocuments(userId);
  const fields = await this.extractor.extract(docs);
  return { ...fields, userId, documentIds: docs.map((d) => d.id), extractedAt: new Date().toISOString() };
}

DocumentStore.latestDocuments.source:
async latestDocuments(userId: string): Promise<IdentityDocument[]> {
  const docs = await this.db.select<IdentityDocument & Record<string, unknown>>('user_documents', { userId });
  return docs.sort((a, b) => b.uploadedAt.localeCompare(a.uploadedAt));
}

DocumentExtractor.extract.source:
async extract(documents: IdentityDocument[]): Promise<ExtractedFields> {
  if (documents.length === 0) throw new Error('no identity documents on file');
  return this.http.post<ExtractedFields>('document-ai', '/v2/extract', { fileRefs: documents.map((d) => d.fileRef) });
}

DocumentBirthExtractor.fromIdentity.source:
fromIdentity(identity: IdentityData): BirthInfo {
  return { countryOfBirth: identity.countryOfBirth, cityOfBirth: identity.cityOfBirth };
}

NationalityModule.resolve.source:
async resolve(identity: IdentityData): Promise<Nationality> {
  const [country] = await this.db.select<Nationality & Record<string, unknown>>('country_codes', { alpha3: identity.nationality });
  return country ?? { alpha3: identity.nationality, name: identity.nationality, isEu: false };
}

SanctionsScreening.screen.source:
async screen(person: { name: string; countryOfBirth: string; nationality: string }): Promise<ScreeningResult> {
  const query = { ...person, name: normaliseName(person.name) };
  let response: { hit: boolean; score?: number; listVersion: string };
  try {
    response = await this.http.post('sanctions-api', '/v2/screen', query);
  } catch {
    // The list provider times out under load; one retry is cheaper than failing the whole KYC check.
    response = await this.http.post('sanctions-api', '/v2/screen', query);
  }
  return { hit: response.hit, score: response.score ?? (response.hit ? 1 : 0), listVersion: response.listVersion };
}

KycModule.getStatus.source:
async getStatus(userId: string): Promise<KycResult | undefined> {
  const [latest] = await this.db.select<KycResult & Record<string, unknown>>('kyc_results', { userId });
  return latest;
}

KycModule.override.source:
async override(userId: string, status: KycStatus, reviewer: string) {
  await this.db.update('kyc_results', { userId }, { status, overriddenBy: reviewer });
  await this.outbox.enqueue('kyc.overridden', { userId, status, reviewer });
  return { userId, status };
}

KycModule.recheckExpired.source:
async recheckExpired(): Promise<number> {
  const expired = await this.db.select<KycResult & Record<string, unknown>>('kyc_results', { status: 'expired' });
  for (const row of expired) await this.outbox.enqueue('kyc.recheck_requested', { userId: row.userId });
  return expired.length;
}

OnboardingModule.complete.source:
async complete(userId: string) {
  const kyc = await this.kyc.runCheck(userId);
  if (kyc.status !== 'passed') return { userId, onboarded: false };
  await this.db.update('users', { userId }, { status: 'active' });
  await this.kafka.produce('user.onboarded', { userId });
  return { userId, onboarded: true };
}
